	void *ptr;
	GLOBAL_INT_DECLARATION();

	GLOBAL_INT_DISABLE();
	ptr = scan_rst_set_ptr;
	if (ptr != NULL)
		scan_rst_set_ptr->ref += 1;
	GLOBAL_INT_RESTORE();

